import React, {
  ElementRef,
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
} from 'react';

import { useBeforeInputHandler } from './hooks/useBeforeInputHandler.js';
import {
  NumberSpinButtonContextProvider,
  useNumberSpinButtonContext,
} from './hooks/useNumberSpinButtonContext.js';
import { useValidateAndSanitize } from './hooks/useValidateAndSanitize.js';
import { useValueNavigation } from './hooks/useValueNavigation.js';
import type { _NumberSpinButtonProps, _NumberSpinButtonRef } from './types.js';
import { useSelection } from '../hooks/useSelection.js';
import { spinButtonStyle } from '../SpinButton.sty.js';

/**
 * */
const NumberSpinButtonWithContext = /* @__PURE__ */ forwardRef<
  _NumberSpinButtonRef,
  _NumberSpinButtonProps
>((props, forwardedRef) => {
  const {
    disabled = false,
    readonly = false,
    value: valueProp,
    placeholder,
  } = props;
  const rootRef = useRef<ElementRef<'span'>>(null);

  const { error, applyText, setError, defaultValue, clearValue } =
    useNumberSpinButtonContext();
  const { getSelection, setSelection, selectAll, deselectAll } =
    useSelection(rootRef);

  const { value } = useNumberSpinButtonContext();
  const beforeInputHandler = useBeforeInputHandler(rootRef, props);
  const { keyDownHandler } = useValueNavigation(rootRef, props);
  const { validate, format } = useValidateAndSanitize(props);

  // Provide root element reference and functions
  useImperativeHandle(
    forwardedRef,
    () => ({
      type: 'number' as const,
      element: rootRef,
      setSelection,
      getSelection,
      selectAll,
      deselectAll,
      applyText: (input: string, fireOnChange) =>
        applyText(input, rootRef.current, fireOnChange),
      clearValue: (fireOnChange) => clearValue(rootRef.current, fireOnChange),
    }),
    [setSelection, getSelection, selectAll, deselectAll, clearValue, applyText],
  );

  // Set errorstate on value change
  useEffect(() => {
    const isValid = validate(value);
    setError(!isValid);
  }, [setError, validate, value]);

  // Set initial value on first render
  useEffect(() => {
    applyText(
      defaultValue === null || Number.isNaN(defaultValue)
        ? ''
        : defaultValue.toString(),
      rootRef.current,
    );
    // Only apply default value when component is mounted. Ignore subsequent defaultValue state updates.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [applyText, format]);

  // Register native beforeInput event handler. The syntethic event is not sufficient for the required features.
  useEffect(() => {
    const element = rootRef.current;
    element?.addEventListener('beforeinput', beforeInputHandler);
    return () =>
      element?.removeEventListener('beforeinput', beforeInputHandler);
  }, [beforeInputHandler]);

  // Handle internal state update if component is in controlled mode
  useEffect(() => {
    // No value prop. provided ==> component is uncontrolled
    if (valueProp === undefined) {
      return;
    }

    // Update internal state
    const sel = getSelection();
    applyText(
      valueProp !== null && Number.isInteger(valueProp)
        ? format(valueProp)
        : '',
      rootRef.current,
    );

    // Only restore the selection for the spinbutton currently focused
    document.activeElement === rootRef.current && sel && setSelection(sel);
  }, [valueProp, applyText, format, getSelection, setSelection]);

  return (
    <span
      ref={rootRef}
      tabIndex={0}
      contentEditable={!disabled && !readonly}
      spellCheck={false}
      className={spinButtonStyle({ disabled, error })}
      style={
        {
          '--data-placeholder': `"${placeholder ?? ''}"`,
        } as React.CSSProperties
      }
      aria-disabled={disabled}
      aria-label={placeholder}
      role="spinbutton"
      onFocus={() => {
        selectAll();
        rootRef.current?.scrollIntoView({
          block: 'nearest',
          inline: 'nearest',
        });
      }}
      onBlur={deselectAll}
      onKeyDown={keyDownHandler}
    />
  );
});

/**
 * @internal
 * Use the _NumberSpinButton component to show a number that can be changed using arrow and page keys.
 * */
export const _NumberSpinButton = /* @__PURE__ */ forwardRef<
  _NumberSpinButtonRef,
  _NumberSpinButtonProps
>((props, forwardedRef) => {
  return (
    <NumberSpinButtonContextProvider {...props}>
      <NumberSpinButtonWithContext ref={forwardedRef} {...props} />
    </NumberSpinButtonContextProvider>
  );
});

(
  _NumberSpinButton as typeof _NumberSpinButton & { displayName: string }
).displayName = '_NumberSpinButton';
